protected InteractionParticle(ClientWorld world, double x, double y, double z) {
        super(world, x, y, z);
        this.velocityX *= 0.01F;
        this.velocityY *= 0.01F;
        this.velocityZ *= 0.01F;
        this.velocityY += 0.1D;
        this.scale *= 1.5F;
        this.maxAge = 20;
        this.collidesWithWorld = false;
    }

