public static NativeImage portLegacySkin(NativeImage image) {
        NativeImage ported = new NativeImage(64, 64, false);

        // copy upper part
        for (int x = 0; x < 64; x++) {
            for (int y = 0; y < 32; y++) {
                ported.setColor(x, y, image.getColor(x, y));
            }
        }

        // clear lower part
        for (int x = 0; x < 64; x++) {
            for (int y = 32; y < 64; y++) {
                ported.setColor(x, y, 0);
            }
        }

        // copy new parts
        for (UVMapping mapping : mappings) {
            for (int x = mapping.x0; x < mapping.x1; x++) {
                for (int y = mapping.y0; y < mapping.y1; y++) {
                    ported.setColor(x + mapping.offsetX, y + mapping.offsetY, image.getColor(mapping.flip ? (mapping.x1 - (x - mapping.x0) - 1) : x, y));
                }
            }
        }

        image.close();
        return ported;
    }

public static boolean isSlimFormat(NativeImage image) {
        return image.getOpacity(54, 25) == 0;
    }

public static void convertSlimToDefault(NativeImage image) {
        stretch(image, 40, 20);
        stretch(image, 40, 36);
        stretch(image, 32, 52);
        stretch(image, 48, 52);
    }

private static void stretch(NativeImage image, int offsetX, int offsetY) {
        int target = offsetX + 16 - 1;
        int original = offsetX + 14 - 1;
        for (int p = 0; p < 12; p++) {
            for (int y = 0; y < 12; y++) {
                image.setColor(target, offsetY + y, image.getColor(original, offsetY + y));
            }
            target--;
            if (p != 6 && p != 9) {
                original--;
            }
        }

        offsetY -= 4;
        target = offsetX + 16 - 1 - 4;
        original = offsetX + 14 - 1 - 4;
        for (int p = 0; p < 8; p++) {
            for (int y = 0; y < 4; y++) {
                image.setColor(target, offsetY + y, image.getColor(original, offsetY + y));
            }
            target--;
            if (p != 1 && p != 5) {
                original--;
            }
        }
    }

private static void setInMemoryAudio(String identifier, ByteBuffer buffer) {
        if (inMemory.containsKey(identifier)) {
            inMemory.get(identifier).setBuffer(buffer);
        } else {
            inMemory.put(identifier, new PCMAudioStream(buffer));
        }
    }

public static PCMAudioStream getPCMAudioStream(String identifier) {
        if (inMemory.containsKey(identifier)) {
            return inMemory.get(identifier);
        } else {
            return new PCMAudioStream(readFromDisk(identifier));
        }
    }

public static boolean get(String identifier, Consumer<OutputStream> retriever, boolean persistent) {
        if (persistent) {
            return cachedRetrieve(identifier, retriever);
        } else {
            ByteBuffer byteBuffer = retrieve(retriever);
            if (byteBuffer == null) {
                return false;
            } else {
                AudioCache.setInMemoryAudio(identifier, byteBuffer);
                return true;
            }
        }
    }

private static ByteBuffer retrieve(Consumer<OutputStream> retriever) {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            retriever.accept(baos);
            return ByteBuffer.wrap(baos.toByteArray());
        } catch (IOException e) {
            return null;
        }
    }

public static ByteBuffer readFromDisk(String identifier) {
        File cacheFile = new File(CACHE_DIR, identifier);
        if (!isSane(cacheFile)) return null;

        try (FileInputStream fis = new FileInputStream(cacheFile)) {
            return ByteBuffer.wrap(fis.readAllBytes());
        } catch (IOException e) {
            MCA.LOGGER.error("Failed to retrieve cached audio file: {}", identifier, e);
            return null;
        }
    }

public static boolean cachedRetrieve(String identifier, Consumer<OutputStream> retriever) {
        try {
            File cacheFile = new File(CACHE_DIR, identifier);
            if (isSane(cacheFile)) {
                return true;
            } else {
                //noinspection ResultOfMethodCallIgnored
                cacheFile.getParentFile().mkdirs();
                try (FileOutputStream fos = new FileOutputStream(cacheFile)) {
                    retriever.accept(fos);
                }
                return isSane(cacheFile);
            }
        } catch (IOException e) {
            MCA.LOGGER.error("Failed to cache audio file: {}", identifier, e);
            return false;
        }
    }

private static boolean isSane(File cacheFile) {
        return cacheFile.exists() && cacheFile.length() > MIN_SIZE;
    }

public static String getHash(String text) {
        MESSAGEDIGEST.update(text.getBytes());
