@Inject(method = "get", at = @At("HEAD"), cancellable = true)
    private void mca$onGet(String key, String fallback, CallbackInfoReturnable<String> info) {
        String modifiedKey = DialogueType.applyFallback(key);

        Pair<String, String> unpooled = mca$getPool().get(modifiedKey);
        if (unpooled != null) {
            CommonSpeechManager.INSTANCE.lastResolvedKey = unpooled.getLeft();
            if (translations.containsKey(unpooled.getLeft()) && !translations.get(unpooled.getLeft()).equals(unpooled.getRight())) {
                // In this case, the text has been dynamically created and we need to return directly
                info.setReturnValue(unpooled.getRight());
            } else {
                info.setReturnValue(get(unpooled.getLeft(), fallback));
            }
        } else if (!key.equals(modifiedKey)) {
            info.setReturnValue(get(modifiedKey, fallback));
        }
    }

@Inject(method = "hasTranslation(Ljava/lang/String;)Z", at = @At("HEAD"), cancellable = true)
    public void mca$onHasTranslation(String key, CallbackInfoReturnable<Boolean> info) {
        if (mca$getPool().contains(key)) {
            info.setReturnValue(true);
        }
    }

@Override
    public void handleGuiRequest(OpenGuiRequest message) {
        Entity entity;
        assert client.world != null;
        assert MinecraftClient.getInstance().player != null;
        switch (message.getGui()) {
            case WHISTLE:
                client.setScreen(new WhistleScreen());
                break;
            case BOOK:
                if (client.player != null) {
                    ItemStack item = client.player.getStackInHand(Hand.MAIN_HAND);
                    if (item.getItem() instanceof ExtendedWrittenBookItem bookItem) {
                        Book book = bookItem.getBook(item);
                        client.setScreen(new ExtendedBookScreen(book));
                    }
                }
                break;
            case BLUEPRINT:
                client.setScreen(new BlueprintScreen());
                break;
            case INTERACT:
                if (client.player != null) {
                    ItemStack item = client.player.getStackInHand(Hand.MAIN_HAND);
                    boolean isOnBlacklist = Config.getInstance().villagerInteractionItemBlacklist.contains(Registries.ITEM.getId(item.getItem()).toString());
                    if (!isOnBlacklist) {
                        VillagerLike<?> villager = (VillagerLike<?>) client.world.getEntityById(message.villager);
                        client.setScreen(new InteractScreen(villager));
                    }
                }
                break;
            case VILLAGER_EDITOR:
                entity = client.world.getEntityById(message.villager);
                assert entity != null;
                client.setScreen(new VillagerEditorScreen(entity.getUuid(), MinecraftClient.getInstance().player.getUuid()));
                break;
            case LIMITED_VILLAGER_EDITOR:
                entity = client.world.getEntityById(message.villager);
                assert entity != null;
                client.setScreen(new LimitedVillagerEditorScreen(entity.getUuid(), MinecraftClient.getInstance().player.getUuid()));
                break;
            case NEEDLE_AND_THREAD:
                entity = client.world.getEntityById(message.villager);
                if (entity == null) {
                    client.setScreen(new NeedleScreen(MinecraftClient.getInstance().player.getUuid()));
                } else {
                    client.setScreen(new NeedleScreen(entity.getUuid(), MinecraftClient.getInstance().player.getUuid()));
                }
                break;
            case COMB:
                entity = client.world.getEntityById(message.villager);
                if (entity == null) {
                    client.setScreen(new CombScreen(MinecraftClient.getInstance().player.getUuid()));
                } else {
                    client.setScreen(new CombScreen(entity.getUuid(), MinecraftClient.getInstance().player.getUuid()));
                }
                break;
            case BABY_NAME:
                if (client.player != null) {
                    ItemStack item = client.player.getStackInHand(Hand.MAIN_HAND);
                    if (item.getItem() instanceof BabyItem) {
                        client.setScreen(new NameBabyScreen(client.player, item));
                    }
                }
                break;
            case FAMILY_TREE:
                client.setScreen(new FamilyTreeSearchScreen());
                break;
            case VILLAGER_TRACKER:
                client.setScreen(new VillagerTrackerSearchScreen());
                break;
            default:
        }
    }

