        synchronized (tombstones) {
            tombstones.forEach((state, chunks) -> {
                NbtCompound chunkList = new NbtCompound();

                chunks.long2ObjectEntrySet().forEach(entry -> {
                    if (!entry.getValue().isEmpty()) {
