public VillageGuardsManager(Village village) {
        this.village= village;
    }

public void spawnGuards(ServerWorld world) {
        int guardCapacity = (int)Math.ceil(village.getPopulation() * Config.getInstance().guardSpawnFraction);

        // Count up the guards
        int guards = 0;
        int citizen = 0;
        List<VillagerEntityMCA> villagers = village.getResidents(world);
        List<VillagerEntityMCA> nonGuards = new LinkedList<>();
        for (VillagerEntityMCA villager : villagers) {
            if (villager.isGuard()) {
                guards++;
            } else {
                if (!villager.isBaby() && !villager.isProfessionImportant() && villager.getExperience() == 0 && villager.getVillagerData().getLevel() <= 1) {
                    nonGuards.add(villager);
                }
                citizen++;
            }
        }

        // Count all unloaded villagers against the guard limit
        // This is statistical and may not be accurate, but it's better than nothing
        guards += Math.ceil((village.getPopulation() - guards - citizen) * Config.getInstance().guardSpawnFraction);

        // Spawn a new guard if we don't have enough
        if (nonGuards.size() > 0 && guards < guardCapacity) {
            VillagerEntityMCA villager = nonGuards.get(world.random.nextInt(nonGuards.size()));
            villager.setProfession(guards % 2 == 0 ? ProfessionsMCA.GUARD.get() : ProfessionsMCA.ARCHER.get());
        }
    }

public EquipmentSet getGuardEquipment(VillagerProfession profession, Hand dominantHand) {
        if (profession == ProfessionsMCA.ARCHER.get()) {
            if (village.hasBuilding("armory")) {
                if (village.hasBuilding("blacksmith")) {
                    return getEquipmentFor(dominantHand, EquipmentSet.ARCHER_2, EquipmentSet.ARCHER_2_LEFT);
                } else {
                    return getEquipmentFor(dominantHand, EquipmentSet.ARCHER_1, EquipmentSet.ARCHER_1_LEFT);
                }
            } else {
                return getEquipmentFor(dominantHand, EquipmentSet.ARCHER_0, EquipmentSet.ARCHER_0_LEFT);
            }
        } else {
            if (village.hasBuilding("armory")) {
                if (village.hasBuilding("blacksmith")) {
                    return EquipmentSet.GUARD_2;
                } else {
                    return EquipmentSet.GUARD_1;
                }
            } else {
                return getEquipmentFor(dominantHand, EquipmentSet.GUARD_0, EquipmentSet.GUARD_0_LEFT);
            }
        }
    }

public static EquipmentSet getEquipmentFor(Hand dominantHand, EquipmentSet rightSet, EquipmentSet leftSet) {
        return dominantHand == Hand.OFF_HAND && leftSet != null ? leftSet : rightSet;
    }

public VillageInnManager(Village village) {
        this.village = village;
    }

public void updateInn(ServerWorld world) {
        village.getBuildingsOfType("inn").forEach(b -> {
            if (world.random.nextFloat() < Config.getInstance().adventurerAtInnChancePerMinute) {
                List<BlockPos> values = new ArrayList<>(b.getBlocks().values().stream().flatMap(Collection::stream).toList());
                Collections.shuffle(values);
                for (BlockPos p : values) {
                    if (trySpawnAdventurer(world, p.up())) {
                        break;
                    }
                }
            }
        });
    }

private boolean doesNotSuffocateAt(BlockView world, BlockPos pos) {
        for (BlockPos blockPos : BlockPos.iterate(pos, pos.up())) {
            if (world.getBlockState(blockPos).getCollisionShape(world, blockPos).isEmpty()) continue;
            return false;
        }
        return true;
    }

private boolean trySpawnAdventurer(ServerWorld world, BlockPos blockPos) {
        if (!world.shouldTickEntity(blockPos)) {
            // prevent any additional retries
            return true;
        }

        String name = null;
        if (this.doesNotSuffocateAt(world, blockPos)) {
            int i = world.random.nextInt(10);
            if (i == 0 && Config.getInstance().innSpawnsWanderingTraders) {
                WanderingTraderEntity trader = EntityType.WANDERING_TRADER.spawn(world, blockPos, SpawnReason.EVENT);
                if (trader != null) {
                    name = trader.getName().getString();
                    trader.setDespawnDelay(Config.getInstance().adventurerStayTime);
                }
            } else if (i == 1 && Config.getInstance().innSpawnsCultists) {
                VillagerEntityMCA adventurer = spawnInnVillager(world, blockPos, Gender.getRandom());
                if (adventurer != null) {
                    name = adventurer.getName().getString();
                    adventurer.setProfession(ProfessionsMCA.CULTIST.get());
                    adventurer.setDespawnDelay(Config.getInstance().adventurerStayTime);
                }
            } else if (Config.getInstance().innSpawnsAdventurers) {
                VillagerEntityMCA adventurer = spawnInnVillager(world, blockPos, Gender.getRandom());
                if (adventurer != null) {
                    name = adventurer.getName().getString();
                    adventurer.setProfession(ProfessionsMCA.ADVENTURER.get());
                    adventurer.setDespawnDelay(Config.getInstance().adventurerStayTime);
                }
            }

            if (name != null) {
                if (Config.getInstance().innArrivalNotification) {
                    village.broadCastMessage(world, "events.arrival.inn", name);
                }
                return true;
            }
        }
        return false;
    }

private VillagerEntityMCA spawnInnVillager(ServerWorld world, BlockPos blockPos, Gender gender) {
        VillagerEntityMCA adventurer = gender.getVillagerType().spawn(world, blockPos, SpawnReason.EVENT);
        if (adventurer != null) {
            adventurer.setCustomName(Text.literal(Names.pickCitizenName(gender)));
        }
        return adventurer;
    }

public VillageMarriageManager(Village village) {
        this.village = village;
    }

public void marry(ServerWorld world) {
        if (world.random.nextFloat() >= Config.getInstance().marriageChancePerMinute) {
            return;
        }

        //list all lonely villagers
        List<VillagerEntityMCA> allVillagers = village.getResidents(world);
        List<VillagerEntityMCA> availableVillagers = allVillagers.stream()
                .filter(v -> !v.isBaby())
                .filter(v -> !v.getRelationships().isMarried())
                .filter(v -> !v.getRelationships().isEngaged())
                .filter(v -> !v.getRelationships().isPromised())
                .collect(Collectors.toList());

        if (availableVillagers.size() <= 1 || availableVillagers.size() <= allVillagers.size() * (1.0 - village.getMarriageThreshold())) {
            return; // The village is too small.
        }

        //use the one with the least max hearts
        //this feels random yet respects relationships
        availableVillagers.sort(Comparator.comparingInt(a -> a.getVillagerBrain().getMemories().values().stream().map(Memories::getHearts).max(Integer::compare).orElse(0)));

        VillagerEntityMCA suitor = availableVillagers.remove(0);

        // Find a potential mate
        availableVillagers.stream()
                .filter(suitor::canBeAttractedTo)
                .filter(i -> !suitor.getRelationships().getFamilyEntry().isRelative(i.getUuid()))
                .findFirst().ifPresent(mate -> {
                    suitor.getRelationships().marry(mate);
                    mate.getRelationships().marry(suitor);

                    // tell everyone about it
                    if (Config.getInstance().villagerMarriageNotification) {
                        village.broadCastMessage(world, "events.marry", suitor, mate);
                    }

                    // civil entry
                    village.getCivilRegistry().ifPresent(r -> r.addText(Text.translatable("events.marry", suitor.getName(), mate.getName())));
                });
    }

public VillageProcreationManager(Village village) {
        this.village= village;
    }

public void procreate(ServerWorld world) {
        if (world.random.nextFloat() >= Config.getInstance().villagerProcreationChancePerMinute) {
            return;
        }

        int population = village.getPopulation();
        int maxPopulation = village.getMaxPopulation();
        if (population >= maxPopulation * village.getPopulationThreshold()) {
            return;
        }

        // look for married women without baby
        PoolUtil.pick(village.getResidents(world), world.random)
                .filter(villager -> villager.getGenetics().getGender() == Gender.FEMALE)
                .filter(villager -> world.random.nextFloat() < 1.0 / (FamilyTree.get(world).getOrCreate(villager).getChildren().count() + 0.1))
                .filter(villager -> villager.getRelationships().getPregnancy().tryStartGestation())
                .ifPresent(villager ->
                        villager.getRelationships().getPartner().ifPresent(spouse -> {
                                    // tell everyone about it
                                    if (Config.getInstance().villagerBirthNotification && spouse instanceof VillagerEntityMCA spouseVillager) {
                                        village.broadCastMessage(world, "events.baby", villager, spouseVillager);
                                    }
                                }
                        )
                );
    }

public VillageTaxesManager(Village village) {
        this.village = village;
    }

public void taxes(ServerWorld world) {
        double taxes = Config.getInstance().taxesFactor * village.getPopulation() * village.getTaxes() + world.random.nextDouble();
        int moodImpact = 0;

        //response
        Text msg;
        float r = village.getTaxes() + (world.random.nextFloat() - 0.5f) * world.random.nextFloat();
        if (village.getTaxes() == 0.0f) {
            msg = Text.translatable("gui.village.taxes.no", village.getName()).formatted(Formatting.GREEN);
            moodImpact = 5;
            taxes = 0.0;
        } else if (r < 0.1) {
            msg = Text.translatable("gui.village.taxes.more", village.getName()).formatted(Formatting.GREEN);
            taxes += village.getPopulation() * 0.25;
        } else if (r < 0.3) {
            msg = Text.translatable("gui.village.taxes.happy", village.getName()).formatted(Formatting.DARK_GREEN);
            moodImpact = 5;
        } else if (r < 0.7) {
            msg = Text.translatable("gui.village.taxes", village.getName());
        } else if (r < 0.8) {
            msg = Text.translatable("gui.village.taxes.sad", village.getName()).formatted(Formatting.GOLD);
            moodImpact = -5;
        } else if (r < 0.9) {
            msg = Text.translatable("gui.village.taxes.angry", village.getName()).formatted(Formatting.RED);
            moodImpact = -10;
        } else {
            msg = Text.translatable("gui.village.taxes.riot", village.getName()).formatted(Formatting.DARK_RED);
            taxes = 0;
        }

        //send all player with rank merchant a notification
        world.getPlayers().stream()
                .filter(v -> Tasks.getRank(village, v).isAtLeast(Rank.MERCHANT))
                .forEach(player -> player.sendMessage(msg, true));

        //upgrades
        if (village.hasBuilding("library")) {
            taxes *= 1.5;
        }

        //choose as many items as possible
        while (taxes > 0.0) {
            double finalTaxes = taxes;

            // create a weighted list of all available items
            List<String> valids = Config.getInstance().taxesMap.entrySet().stream()
                    .filter(e -> e.getValue() * world.random.nextFloat() < finalTaxes)
                    .map(Map.Entry::getKey)
                    .toList();

            if (valids.isEmpty()) {
                break;
            }

            // pick a random item
            String itemName = valids.get(world.random.nextInt(valids.size()));
            Item item = Registries.ITEM.get(new Identifier(itemName));

            if (item == Items.AIR) {
                throw new RuntimeException("The taxes map contains an invalid item %s!" .formatted(itemName));
            }

            // pay the price
            taxes -= Config.getInstance().taxesMap.get(itemName);

            // stack it or create a new item
            Optional<ItemStack> stack = village.storageBuffer.stream().filter(i -> i.isOf(item) && i.getCount() < i.getMaxCount()).findAny();
            if (stack.isPresent()) {
                stack.get().increment(1);
            } else if (village.storageBuffer.size() < MAX_STORAGE_SIZE) {
                village.storageBuffer.add(new ItemStack(item, 1));
            }
        }

        if (moodImpact != 0) {
            village.pushMood(moodImpact * village.getPopulation());
        }

        deliverTaxes(world);
    }

public void deliverTaxes(ServerWorld world) {
        if (village.hasStoredResource() && WorldUtils.isChunkLoaded(world, village.getCenter())) {
            village.getBuildingsOfType("storage").forEach(building -> building.getBlocks().values().stream()
                    .flatMap(Collection::stream)
                    .forEach(p -> {
                        if (village.hasStoredResource()) {
                            tryToPutIntoInventory(world, p);
                        }
                    }));
        }
    }

private void tryToPutIntoInventory(ServerWorld world, BlockPos p) {
        BlockState state = world.getBlockState(p);
        if (state.hasBlockEntity()) {
            BlockEntity blockEntity = world.getBlockEntity(p);
            if (blockEntity instanceof Inventory inventory) {
                Block block = state.getBlock();
                if (inventory instanceof ChestBlockEntity && block instanceof ChestBlock chest) {
                    inventory = ChestBlock.getInventory(chest, state, world, p, true);
                    if (inventory != null) {
                        putIntoInventory(inventory);
                    }
                }
            }
        }
    }

private void putIntoInventory(Inventory inventory) {
        for (int i = 0; i < inventory.size(); i++) {
            boolean changes = true;
            while (changes) {
                changes = false;
                ItemStack stack = inventory.getStack(i);
                ItemStack tax = village.storageBuffer.get(0);
                if (stack.getItem() == tax.getItem()) {
                    int diff = Math.min(tax.getCount(), stack.getMaxCount() - stack.getCount());
                    if (diff > 0) {
                        stack.increment(diff);
                        tax.decrement(diff);
                        if (tax.isEmpty()) {
                            village.storageBuffer.remove(0);
                            changes = true;
                        }
                        inventory.markDirty();
                    }
                } else if (stack.isEmpty()) {
                    inventory.setStack(i, tax);
                    inventory.markDirty();
                    village.storageBuffer.remove(0);
                    changes = true;
                }
                if (!village.hasStoredResource()) {
                    return;
                }
            }
        }
    }

