					return crib.getColor() == color && crib.getWood() == wood;
				}).findFirst().orElse(ItemsMCA.CRIBS.get(0)).get();

				Model cribModel = new Model(Optional.of(new Identifier("minecraft", "item/generated")), Optional.empty(), TextureKey.LAYER0, TextureKey.LAYER1);

				cribModel.upload(ModelIds.getItemModelId(item), TextureMap.layered(MCA.locate("item/crib/beds/" + color.getName()),
					MCA.locate("item/crib/frames/" + wood.toString().toLowerCase(Locale.ROOT))), itemModelGenerator.writer);
			}
		}
	}

@Override
	public void generateTranslations(TranslationBuilder translationBuilder)
	{
		for(CribWoodType wood : CribWoodType.values())
		{
			for(DyeColor color : DyeColor.values())
			{
				CribItem item = (CribItem) ItemsMCA.CRIBS.stream().filter(c ->
				{
					CribItem crib = (CribItem) c.get();
					return crib.getColor() == color && crib.getWood() == wood;
				}).findFirst().get().get();

				String colorName = "";
				for(String s : item.getColor().getName().split("_"))
				{
					colorName += (s.substring(0, 1).toUpperCase(Locale.ROOT) + s.substring(1) + " ");
				}

				String woodName = "";
				for(String s : item.getWood().toString().toLowerCase(Locale.ROOT).split("_"))
				{
					woodName += (s.substring(0, 1).toUpperCase(Locale.ROOT) + s.substring(1) + " ");
				}

				translationBuilder.add(item, colorName + woodName + "Crib");
			}
		}
	}

@Override
	public void generate(Consumer<RecipeJsonProvider> consumer)
	{
		for(CribWoodType wood : CribWoodType.values())
		{
			for(DyeColor color : DyeColor.values())
			{
				ShapedRecipeJsonBuilder.create(RecipeCategory.DECORATIONS, ItemsMCA.CRIBS.stream().filter(c ->
				{
					CribItem crib = (CribItem) c.get();
					return crib.getColor() == color && crib.getWood() == wood;
				}).findFirst().get().get(), 1)
				.input(Character.valueOf('F'), fenceFromWoodType(wood))
				.input(Character.valueOf('P'), plankFromWoodType(wood))
				.input(Character.valueOf('C'), carpetFromColor(color))
				.pattern("F F")
				.pattern("FCF")
				.pattern("PPP")
				.criterion(RecipeProvider.hasItem(plankFromWoodType(wood)), RecipeProvider.conditionsFromItem(plankFromWoodType(wood)))
				.offerTo(consumer);
			}
		}
	}

private static ItemConvertible plankFromWoodType(CribWoodType woodType)
	{
		switch(woodType)
		{
			case SPRUCE:
				return Blocks.SPRUCE_PLANKS;
			case ACACIA:
				return Blocks.ACACIA_PLANKS;
			case BIRCH:
				return Blocks.BIRCH_PLANKS;
			case CHERRY:
				return Blocks.CHERRY_PLANKS;
			case CRIMSON:
				return Blocks.CRIMSON_PLANKS;
			case DARK_OAK:
				return Blocks.DARK_OAK_PLANKS;
			case JUNGLE:
				return Blocks.JUNGLE_PLANKS;
			case MANGROVE:
				return Blocks.MANGROVE_PLANKS;
			case WARPED:
				return Blocks.WARPED_PLANKS;
			case BAMBOO:
				return Blocks.BAMBOO_PLANKS;
			default:
